package com.timetrackingexport;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Map;

/**
 * Renders Time Tracking data as a Java properties file that uses the same keys as RuneLite's
 * own profile config, so anything that can read one can read the other:
 *
 * <pre>
 * rsprofile.rsprofile.AbCd1234.displayName=Zezima
 * rsprofile.rsprofile.AbCd1234.type=STANDARD
 * timetracking.rsprofile.AbCd1234.11062.4774=32\:1700000000
 * </pre>
 *
 * The output is sorted, so the same data always renders to the same text.
 */
final class ExportFormat
{
	static final String TIME_TRACKING_GROUP = "timetracking";
	static final String RSPROFILE_GROUP = "rsprofile";

	static final String HEADER =
		"# Time Tracking plugin data, written by the Time Tracking Export plugin.\n" +
		"# Keys match RuneLite's own config: timetracking.<profile>.<key>=<value>\n";

	private ExportFormat()
	{
	}

	static String render(Collection<ProfileExport> profiles)
	{
		List<ProfileExport> sorted = new ArrayList<>(profiles);
		sorted.sort(Comparator.comparing(ProfileExport::getKey));

		StringBuilder out = new StringBuilder(HEADER);
		for (ProfileExport profile : sorted)
		{
			String profileKey = RSPROFILE_GROUP + '.' + profile.getKey();
			if (profile.getDisplayName() != null)
			{
				line(out, profileKey + ".displayName", profile.getDisplayName());
			}
			if (profile.getType() != null)
			{
				line(out, profileKey + ".type", profile.getType());
			}

			String prefix = TIME_TRACKING_GROUP + '.' + profile.getKey() + '.';
			for (Map.Entry<String, String> entry : profile.getValues().entrySet())
			{
				line(out, prefix + entry.getKey(), entry.getValue());
			}
		}
		return out.toString();
	}

	private static void line(StringBuilder out, String key, String value)
	{
		escape(out, key, true);
		out.append('=');
		escape(out, value, false);
		out.append('\n');
	}

	/**
	 * Escapes text the way {@link java.util.Properties#store} does, so {@link java.util.Properties#load}
	 * reads back exactly what was written.
	 */
	private static void escape(StringBuilder out, String text, boolean isKey)
	{
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			switch (c)
			{
				case ' ':
					// a space ends a key, and leading spaces of a value are skipped
					if (isKey || i == 0)
					{
						out.append('\\');
					}
					out.append(' ');
					break;
				case '\t':
					out.append("\\t");
					break;
				case '\n':
					out.append("\\n");
					break;
				case '\r':
					out.append("\\r");
					break;
				case '\f':
					out.append("\\f");
					break;
				case '\\':
				case '=':
				case ':':
				case '#':
				case '!':
					out.append('\\').append(c);
					break;
				default:
					if (c < 0x20 || c > 0x7e)
					{
						out.append(String.format("\\u%04x", (int) c));
					}
					else
					{
						out.append(c);
					}
			}
		}
	}
}

package com.timetrackingexport;

import java.util.SortedMap;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * One RuneScape profile's Time Tracking data, ready to be written out.
 */
@Value
class ProfileExport
{
	/**
	 * The profile's config key, e.g. {@code rsprofile.AbCd1234}
	 */
	String key;

	@Nullable
	String displayName;

	/**
	 * The profile type's name, e.g. {@code STANDARD}
	 */
	@Nullable
	String type;

	/**
	 * Time Tracking's values for this profile, by config key (e.g. {@code 11062.4774} to {@code 32:1700000000})
	 */
	SortedMap<String, String> values;
}

package com.timetrackingexport;

import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import java.util.SortedMap;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Filepath;

/**
 * Mirrors the Time Tracking plugin's per-account data (farming patches, bird houses and the
 * settings needed to interpret them) to a file as it changes.
 *
 * RuneLite keeps this data in memory and only saves it to its own config file every few minutes,
 * which is too slow for a timer shown outside the client. This plugin reads nothing from the game
 * itself: it copies what Time Tracking has already recorded.
 */
@Slf4j
@PluginDescriptor(
	name = "Time Tracking Export",
	description = "Writes the Time Tracking plugin's farming patch and bird house data to a local file as it changes, for external timer tools",
	tags = {"farming", "birdhouse", "timers", "export", "file", "time tracking"},
	internalName = "time-tracking-export"
)
public class TimeTrackingExportPlugin extends Plugin
{
	static final String FILE_NAME = "timetracking.properties";

	/**
	 * How long to wait after a change before writing, so the several values that change together
	 * when a patch is planted or harvested go out in one write.
	 */
	private static final long WRITE_DELAY_MS = 1000;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ScheduledExecutorService executor;

	private ScheduledFuture<?> pendingWrite;

	/**
	 * What the file currently holds, to skip writes that would change nothing.
	 * Only used on the executor thread.
	 */
	private String lastWritten;

	@Override
	protected void startUp()
	{
		scheduleWrite(0);
	}

	@Override
	protected void shutDown()
	{
		synchronized (this)
		{
			if (pendingWrite != null)
			{
				pendingWrite.cancel(false);
				pendingWrite = null;
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Time Tracking stores per-account data under a RuneScape profile. Its own settings
		// (no profile) say nothing about patches, so they don't trigger a write.
		boolean trackedData = ExportFormat.TIME_TRACKING_GROUP.equals(event.getGroup()) && event.getProfile() != null;
		// A new account, or a renamed one
		boolean profileInfo = ExportFormat.RSPROFILE_GROUP.equals(event.getGroup());
		if (trackedData || profileInfo)
		{
			scheduleWrite(WRITE_DELAY_MS);
		}
	}

	private synchronized void scheduleWrite(long delayMs)
	{
		if (pendingWrite == null)
		{
			pendingWrite = executor.schedule(this::export, delayMs, TimeUnit.MILLISECONDS);
		}
	}

	/**
	 * Runs on the executor, never on the client thread.
	 */
	private void export()
	{
		synchronized (this)
		{
			// From here on a change schedules a new write, since this one may already have read past it.
			pendingWrite = null;
		}

		try
		{
			String content = ExportFormat.render(collect());
			if (content.equals(lastWritten))
			{
				return;
			}

			Filepath directory = getPluginDirectory();
			directory.createDirectories();
			write(directory, content);
			lastWritten = content;
			log.debug("Exported time tracking data ({} characters)", content.length());
		}
		catch (IOException | RuntimeException ex)
		{
			log.warn("Unable to export time tracking data", ex);
		}
	}

	/**
	 * Writes to a temporary file and moves it into place, so a reader never sees half a file.
	 */
	private static void write(Filepath directory, String content) throws IOException
	{
		Filepath target = directory.joinSegment(FILE_NAME);
		Filepath temp = directory.createTempFile("timetracking", ".tmp");
		try
		{
			temp.write(content);
			try
			{
				temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException ex)
			{
				temp.moveTo(target, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		finally
		{
			temp.deleteIfExists();
		}
	}

	private List<ProfileExport> collect()
	{
		List<ProfileExport> profiles = new ArrayList<>();
		for (RuneScapeProfile profile : configManager.getRSProfiles())
		{
			String profileKey = profile.getKey();
			SortedMap<String, String> values = new TreeMap<>();
			for (String key : configManager.getRSProfileConfigurationKeys(ExportFormat.TIME_TRACKING_GROUP, profileKey, ""))
			{
				String value = configManager.getConfiguration(ExportFormat.TIME_TRACKING_GROUP, profileKey, key);
				if (value != null)
				{
					values.put(key, value);
				}
			}

			if (!values.isEmpty())
			{
				String type = profile.getType() == null ? null : profile.getType().name();
				profiles.add(new ProfileExport(profileKey, profile.getDisplayName(), type, values));
			}
		}
		return profiles;
	}
}

package com.timetrackingexport;

import java.io.IOException;
import java.io.StringReader;
import java.util.Arrays;
import java.util.Collections;
import java.util.Properties;
import java.util.SortedMap;
import java.util.TreeMap;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ExportFormatTest
{
	private static SortedMap<String, String> values(String... keysAndValues)
	{
		SortedMap<String, String> map = new TreeMap<>();
		for (int i = 0; i < keysAndValues.length; i += 2)
		{
			map.put(keysAndValues[i], keysAndValues[i + 1]);
		}
		return map;
	}

	private static Properties load(String text) throws IOException
	{
		Properties properties = new Properties();
		properties.load(new StringReader(text));
		return properties;
	}

	@Test
	public void usesTheSameKeysAsRuneLitesConfig() throws IOException
	{
		ProfileExport profile = new ProfileExport("rsprofile.AbCd1234", "Zezima", "STANDARD", values(
			"11062.4774", "32:1700000000",
			"11062.4774.compost", "ULTRACOMPOST",
			"birdhouse.1626", "24:1700000100",
			"autoweed", "2"));

		String text = ExportFormat.render(Collections.singletonList(profile));
		assertTrue(text.startsWith(ExportFormat.HEADER));
		// the separator inside a patch value is escaped, exactly as RuneLite writes it
		assertTrue(text.contains("timetracking.rsprofile.AbCd1234.11062.4774=32\\:1700000000\n"));

		Properties properties = load(text);
		assertEquals(6, properties.size());
		assertEquals("Zezima", properties.getProperty("rsprofile.rsprofile.AbCd1234.displayName"));
		assertEquals("STANDARD", properties.getProperty("rsprofile.rsprofile.AbCd1234.type"));
		assertEquals("32:1700000000", properties.getProperty("timetracking.rsprofile.AbCd1234.11062.4774"));
		assertEquals("ULTRACOMPOST", properties.getProperty("timetracking.rsprofile.AbCd1234.11062.4774.compost"));
		assertEquals("24:1700000100", properties.getProperty("timetracking.rsprofile.AbCd1234.birdhouse.1626"));
		assertEquals("2", properties.getProperty("timetracking.rsprofile.AbCd1234.autoweed"));
	}

	@Test
	public void awkwardTextSurvivesARoundTrip() throws IOException
	{
		String name = " Iron = Mán: #1! \\ \t";
		ProfileExport profile = new ProfileExport("rsprofile.x_Y-z0123", name, null, values("odd key", " leading space", "empty", ""));

		Properties properties = load(ExportFormat.render(Collections.singletonList(profile)));
		assertEquals(name, properties.getProperty("rsprofile.rsprofile.x_Y-z0123.displayName"));
		assertEquals(" leading space", properties.getProperty("timetracking.rsprofile.x_Y-z0123.odd key"));
		assertEquals("", properties.getProperty("timetracking.rsprofile.x_Y-z0123.empty"));
		assertFalse(properties.containsKey("rsprofile.rsprofile.x_Y-z0123.type"));
	}

	@Test
	public void sameDataAlwaysRendersTheSameText()
	{
		ProfileExport a = new ProfileExport("rsprofile.aaaaaaaa", "A", "STANDARD", values("2.2", "1:1", "1.1", "1:1"));
		ProfileExport b = new ProfileExport("rsprofile.bbbbbbbb", "B", "STANDARD", values("1.1", "1:1"));

		String forwards = ExportFormat.render(Arrays.asList(a, b));
		assertEquals(forwards, ExportFormat.render(Arrays.asList(b, a)));
		assertTrue(forwards.indexOf("aaaaaaaa.1.1") < forwards.indexOf("aaaaaaaa.2.2"));
		assertTrue(forwards.indexOf("aaaaaaaa") < forwards.indexOf("bbbbbbbb"));
		assertEquals(ExportFormat.HEADER, ExportFormat.render(Collections.emptyList()));
	}
}

package com.timetrackingexport;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TimeTrackingExportPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TimeTrackingExportPlugin.class);
		RuneLite.main(args);
	}
}
